import { signal } from '@vorzelajs/core'
import { For } from '@vorzelajs/dom'

import { accessorOf, useId } from '~/hooks/index.ts'
import { cx } from '~/lib/cx.ts'
import { X } from './icons.tsx'
import styles from './tag-input.module.scss'

export interface TagInputProps {
  value?: string[] | (() => string[])
  defaultValue?: string[]
  onChange?: (tags: string[]) => void
  label?: string
  placeholder?: string
  maxTags?: number
  disabled?: boolean
  className?: string
  id?: string
}

export function TagInput({
  value: valueProp,
  defaultValue = [],
  onChange,
  label = 'Tags',
  placeholder = 'Add a tag…',
  maxTags = 12,
  disabled = false,
  className,
  id,
}: TagInputProps) {
  const [uncontrolled, setUncontrolled] = signal<string[]>(defaultValue)
  const controlled =
    valueProp === undefined ? null : accessorOf<string[]>(valueProp)
  const tags = (): string[] => (controlled ? controlled() : uncontrolled())

  const setTags = (next: string[]): void => {
    if (!controlled) setUncontrolled(next)
    onChange?.(next)
  }

  const [draft, setDraft] = signal('')
  const inputId = id ?? useId('tag-input')
  const atLimit = (): boolean => tags().length >= maxTags

  const add = (raw: string): void => {
    const next = raw.trim().replace(/,$/, '')
    if (!next) return
    const current = tags()
    if (current.length >= maxTags) return
    if (current.some((tag) => tag.toLowerCase() === next.toLowerCase())) {
      setDraft('')
      return
    }
    setTags([...current, next])
    setDraft('')
  }

  const remove = (index: number): void => {
    setTags(tags().filter((_, i) => i !== index))
  }

  return (
    <div className={cx(styles.root, className)}>
      <label htmlFor={inputId} className={styles.label}>
        {label}
      </label>

      <div className={cx(styles.shell, disabled && styles.disabled)}>
        <For each={tags} key={(tag, index) => `${tag}-${index}`}>
          {(tag, index) => (
            <span className={styles.chip}>
              {tag}
              <button
                type="button"
                onClick={() => remove(index)}
                disabled={disabled}
                aria-label={`Remove ${tag}`}
                className={styles.remove}
              >
                <X aria-hidden />
              </button>
            </span>
          )}
        </For>

        <input
          id={inputId}
          value={() => draft()}
          onChange={(event) =>
            setDraft((event.target as HTMLInputElement).value)
          }
          onKeyDown={(event) => {
            if (event.key === 'Enter' || event.key === ',') {
              event.preventDefault()
              add(draft())
            } else if (event.key === 'Backspace' && !draft() && tags().length) {
              remove(tags().length - 1)
            }
          }}
          onBlur={() => add(draft())}
          disabled={() => disabled || atLimit()}
          placeholder={() =>
            atLimit() ? 'Tag limit reached' : placeholder
          }
          aria-describedby={`${inputId}-count`}
          className={styles.control}
        />
      </div>

      <p id={`${inputId}-count`} className={styles.count}>
        {() => `${tags().length} of ${maxTags} tags`}
      </p>
    </div>
  )
}

@use 'styles' as vz;

.root {
  display: flex;
  flex-direction: column;
  gap: vz.space(1.5);
  min-width: 0;
}

.label {
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
}

.shell {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: vz.space(1.5);
  min-height: vz.space(9);
  padding: vz.space(1.5);
  border: 1px solid vz.color('input');
  border-radius: vz.radius('lg');
  background: vz.color('card');
  box-shadow: vz.elevation(1);
  transition:
    border-color vz.duration('base') vz.ease('out'),
    box-shadow vz.duration('base') vz.ease('out');

  &:focus-within {
    border-color: vz.color('ring');
    box-shadow: 0 0 0 3px vz.color('ring', 0.18);
  }

  @include vz.motion-reduce {
    transition: none;
  }
}

.disabled {
  background: vz.color('muted');
  opacity: 0.6;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: vz.space(1);
  padding: 0.125rem vz.space(2);
  border: 1px solid vz.color('border', 0.7);
  border-radius: vz.radius('sm');
  background: vz.color('secondary');
  color: vz.color('secondary-foreground');
  font-size: vz.font-size('xs');
  font-weight: 500;
  line-height: 1.4;
}

.remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: vz.radius('xs');
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;
  transition: color vz.duration('fast') vz.ease('out');

  svg {
    @include vz.icon(3);
  }

  @include vz.hover {
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 1px, 0.6);

  @include vz.disabled {
    pointer-events: none;
    opacity: 0.5;
  }

  @include vz.motion-reduce {
    transition: none;
  }
}

.control {
  flex: 1;
  min-width: 6rem;
  height: vz.space(6);
  padding: 0 vz.space(1);
  border: 0;
  background: transparent;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  outline: none;

  @include vz.placeholder {
    color: vz.color('muted-foreground');
  }

  @include vz.disabled {
    cursor: not-allowed;
  }
}

.count {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  font-variant-numeric: tabular-nums;
}
